import static org.junit.Assert.assertEquals;

public class StringEscapeUtils_escapeJava_TriageGen0Test {













    @Test
    public void testEscapeJava_ComplexMixed() throws IOException {
        StringWriter out = new StringWriter();
        String input = "Quotes: ' and \", Newline: \n, Tab: \t, Backslash: \\, Unicode: \u0001";
        String expected = "Quotes: ' and \\\", Newline: \\n, Tab: \\t, Backslash: \\\\, Unicode: \\u0001";
        StringEscapeUtils.escapeJava(out, input);
        assertEquals(expected, out.toString());
    }


}

package org.apache.commons.lang;

import java.io.*;
